// src/components/ViewSendMessages.jsx
import React, { useEffect, useState, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";
import "./CSS/ViewSendMessages.css";

const ViewSendMessages = () => {
  const { userEmail } = useParams();
  const navigate = useNavigate();
  const currentUser = JSON.parse(localStorage.getItem("currentUser"));
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const scrollRef = useRef(null);

  useEffect(() => {
    if (!currentUser) {
      alert("Session expired. Please login again.");
      navigate("/login");
      return;
    }

    fetch("http://localhost:5000/get-conversation", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user1: currentUser.email,
        user2: userEmail,
      }),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          setMessages(data.messages);
        } else {
          alert("Failed to fetch messages");
        }
      })
      .catch(() => alert("Error fetching messages"));
  }, [currentUser, userEmail, navigate]);

  const handleSend = () => {
    if (!newMessage.trim()) return;

    fetch("http://localhost:5000/send-message", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        sender: currentUser.email,
        receiver: userEmail,
        message: newMessage.trim(),
      }),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          setMessages((prev) => [
            ...prev,
            {
              sender: currentUser.email,
              receiver: userEmail,
              message: newMessage,
              date: new Date().toISOString().split("T")[0],
              time: new Date().toLocaleTimeString(),
            },
          ]);
          setNewMessage("");
          scrollToBottom();
        } else {
          alert("Failed to send message");
        }
      })
      .catch(() => alert("Error sending message"));
  };

  const handleBack = () => navigate("/dashboard");

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  useEffect(scrollToBottom, [messages]);

  return (
    <div className="chat-container">
      <div className="chat-header">
        <button className="back-btn" onClick={handleBack}>
          ←
        </button>
        <div className="chat-user">
          <p>User - {userEmail.split("@")[0]}</p>
          <p>{userEmail}</p>
        </div>
      </div>

      <div className="chat-body" ref={scrollRef}>
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-bubble ${
              msg.sender === currentUser.email ? "sent" : "received"
            }`}
          >
            <p>{msg.message}</p>
            <span className="chat-time">
              {msg.date} {msg.time}
            </span>
          </div>
        ))}
      </div>

      <div className="chat-input-area">
        <button className="file-btn">+File</button>
        <input
          type="text"
          placeholder="message"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleSend()}
        />
        <button className="send-btn" onClick={handleSend}>
          ▶
        </button>
      </div>
    </div>
  );
};

export default ViewSendMessages;
